INSERT INTO raw_postings (id, source, external_id, raw_text, thread_month, posted_at)
OVERRIDING SYSTEM VALUE VALUES
  (2, 'hn', '48747990', 'We The Flywheel | AI-Native Engineers &amp; Operators | REMOTE (worldwide) | Contract &#x2F; Part-time (10–40 hrs&#x2F;wk)<p>We&#x27;re a remote-first digital product studio building across sports media, AI, fitness, and personal branding — 500+ web properties and deeply AI-native workflows. AI does the heavy lifting here, but it&#x27;s the leverage, not the point: we hire for the human judgment, ingenuity, and taste on top of it.<p>Open roles (remote, contract):<p>- Agentic Engineer — ship real software with AI coding agents (Claude Code, Cursor, Aider). You&#x27;re an engineer, not a prompt operator: basic technical foundation in databases, frameworks, integrations, APIs. &lt;30 hrs&#x2F;wk.<p>- Sr Agentic Engineer — architect and own multi-step agent workflows; track record required. &lt;30 hrs&#x2F;wk.<p>- Agentic Operator — the human-in-the-loop: walk user flows, native-language QA of AI output, and the testing agents can&#x27;t do alone (SSO, captchas, mobile apps). 10–40 hrs&#x2F;wk, open to all levels.<p>- AI-Native Tech &amp; Growth Director<p>- Head of Data Science<p>We&#x27;re also hiring across product, growth, design, and PR — full list at the link.<p>Apply &#x2F; all roles: <a href="https:&#x2F;&#x2F;wetheflywheel.com&#x2F;en&#x2F;careers&#x2F;?utm_source=hackernews&amp;utm_medium=forum&amp;utm_campaign=whoishiring_2026-07" rel="nofollow">https:&#x2F;&#x2F;wetheflywheel.com&#x2F;en&#x2F;careers&#x2F;?utm_source=hackernews&amp;...</a>
(feed: <a href="https:&#x2F;&#x2F;wetheflywheel.com&#x2F;en&#x2F;careers&#x2F;feed.xml" rel="nofollow">https:&#x2F;&#x2F;wetheflywheel.com&#x2F;en&#x2F;careers&#x2F;feed.xml</a>)', '2026-07-01', '2026-07-01T15:02:00+00:00'),
  (3, 'hn', '48748003', 'SmarterDx | 150-250k+ + equity + benefits | Remote (US only) | Multiple roles | <a href="https:&#x2F;&#x2F;smarterdx.com&#x2F;careers" rel="nofollow">https:&#x2F;&#x2F;smarterdx.com&#x2F;careers</a><p>SmarterDx builds clinical AI for one of healthcare’s most broken systems: how hospitals get paid for the care they actually deliver.<p>Our physician-designed clinical AI platform reviews the clinical record, understands the nuance of patient care, and helps hospitals capture appropriate reimbursement across the revenue cycle. The core problem is hard: messy clinical data, complex regulations, payer rules, medical reasoning, and real financial stakes. When we get it right, hospitals recover millions in earned revenue, reduce manual review burden, and keep clinical and revenue teams focused on higher-value work.<p>We’ve hit serious scale while keeping the team unusually strong and technical: MD&#x2F;data scientist hybrids, Stanford LLM researchers, former Google and Amazon engineers, former ASF board member, and others who are among the best in their fields. Many teammates have been here since we bootstrapped to $1M+ in contracted revenue before raising capital.<p>In 2025, SmarterDx became part of Smarter Technologies through a $1.1B deal with New Mountain Capital, reaching unicorn status while continuing to operate with the autonomy, urgency, and product velocity that got us here. Before that, we raised $71M from Floodgate, Transformation Capital, and Bessemer, including a $50M Series B.<p>We have real product-market fit: 85+ health systems, 300+ hospital sites, rapid customer growth, and 150% YoY headcount growth (currently at ~550). Now we’re scaling the platform.<p>For more and to apply, see <a href="https:&#x2F;&#x2F;smarterdx.com&#x2F;careers" rel="nofollow">https:&#x2F;&#x2F;smarterdx.com&#x2F;careers</a>', '2026-07-01', '2026-07-01T15:02:50+00:00'),
  (5, 'hn', '48748008', 'WireScreen (Series A) | Senior Software Engineer (Frontend) &amp; Machine Learning Engineer | NYC - hybrid | Full-time | $170k-$220k (frontend) + equity &#x2F; $150-$195k (ML eng) +equity |<p>WireScreen is a fast-growing Sequoia-backed Series A startup building the go-to open source intelligence platform for navigating global supply chains and China-related risk. While China maintains some of the world’s most detailed corporate ownership records, the real challenge is connecting the dots. That’s where we come in: surfacing the networks, relationships, and financial ties behind companies to support national security, compliance, and regulatory oversight.<p>We’re looking for senior software engineers on the frontend to help build the future of our platform: transitioning us to a component-based system all the way through to building beautiful pages that visualize the story of ownership, power, and influence in the Chinese corporate world.<p>For the frontend we’re looking for significant React experience as well as experience with at least one React framework, plus prior experience building or contributing to a component-based design system &amp; data viz work. At least 5 years experience with 8+ being a more likely level for this person.<p>We’re also looking for a machine learning engineers to level up our entity resolution algorithms and expand our use of LLM technology - for that role we’re looking for 4 years experience with training and deploying ML models in clustering problems, so either knowledge graphs, entity resolution, recommendation engines, cohort analysis or outlier&#x2F;anomaly detection.<p>In both cases you’d join an awesome, tight-knit group of great people who are working on real-world problems with big impact.<p>Apply here (Frontend): <a href="https:&#x2F;&#x2F;jobs.ashbyhq.com&#x2F;wirescreen&#x2F;de6daaae-eb03-4551-809d-eaae9ce35b15?utm_source=xgRXlw271G" rel="nofollow">https:&#x2F;&#x2F;jobs.ashbyhq.com&#x2F;wirescreen&#x2F;de6daaae-eb03-4551-809d-...</a>
Apply here (Machine Learning): <a href="https:&#x2F;&#x2F;jobs.ashbyhq.com&#x2F;wirescreen&#x2F;0a29bcab-59eb-4766-941b-643b9fb011e5?utm_source=xgRXlw271G" rel="nofollow">https:&#x2F;&#x2F;jobs.ashbyhq.com&#x2F;wirescreen&#x2F;0a29bcab-59eb-4766-941b-...</a><p>Or you can reach out to me directly at leo.green@wirescreen.ai - I lead recruiting here at WireScreen, but if I don&#x27;t know the answer I&#x27;ll ping our engineering folks and come back to you fast.', '2026-07-01', '2026-07-01T15:02:59+00:00'),
  (26, 'hn', '48749072', 'DoubleVerify (DV Scibids) | Sr. Data Engineer I | ONSITE&#x2F;HYBRID - New York, NY (3x&#x2F;week) | Full-time | $89K–$178K<p>DV Scibids is the AI-powered digital campaign activation arm of DoubleVerify — the market standard for digital media measurement trusted by hundreds of Fortune 500 brands. Our Data Engineering team owns the critical integrations and data flows that connect Scibids&#x27; optimization engine to the broader adtech ecosystem.<p>In this role you will own and build backend services and data pipelines that power product expansion — exploring external partner APIs, designing reliable ingestion and reconciliation layers, exposing internal endpoints for other DV teams, and keeping production systems observable and performant at scale.<p>Stack: Python, SQL, BigQuery, Cloud SQL, Cloud Datastore, Cloud Run (GCP), Prefect, Docker, CI&#x2F;CD, Git. Java or Rust a plus.<p>Looking for: 3+ years in data engineering or backend engineering. Strong Python and SQL. Experience integrating with external APIs and operating production data systems at scale. Comfort with cloud-native environments and modern engineering practices. AdTech&#x2F;auction-system familiarity is a plus, not required. We use an AI-augmented dev style — familiarity with Claude Code or Cursor is welcome but not mandatory.<p>Apply: <a href="https:&#x2F;&#x2F;boards.greenhouse.io&#x2F;doubleverify&#x2F;jobs&#x2F;7513841002" rel="nofollow">https:&#x2F;&#x2F;boards.greenhouse.io&#x2F;doubleverify&#x2F;jobs&#x2F;7513841002</a>', '2026-07-01', '2026-07-01T16:04:27+00:00'),
  (829, 'remotive', '2091081', '{"id": 2091081, "url": "https://remotive.com/remote-jobs/design/senior-graphic-designer-2091081", "title": "Senior Graphic Designer", "company_name": "Lemon.io", "company_logo": "https://remotive.com/job/2091081/logo", "category": "Design", "tags": [".Net", "android", "C", "C#", "C++", "data science", "golang", "illustrator", "ios", "java", "javascript", "node.js", "php", "python", "react", "ruby/rails", "scala", "shopify", "swift", "wordpress", "blockchain", "AI/ML", "automation", "project management", "adobe creative suite", "react native", "rust", "unity", "electron", "spring", "laravel", "Ethereum", "graphic design", "Typescript ", "angular ", "data engineering", "Site Reliability", "SOLID", "Symfony", "startup", "marketplace", "next.js", "adobe illustrator", "flutter"], "job_type": "full_time", "publication_date": "2026-07-28T14:23:05", "candidate_required_location": "Americas, Europe, Asia, Africa, Oceania", "salary": "", "description": "<p>Are you a talented Senior Designer looking for a remote job that lets you show your skills and get decent compensation? Look no further than <span class=\"notion-enable-hover\" style=\"color: #c14c8a; fill: #c14c8a; isolation: auto;\"><a href=\"https://lemon.io/for-developers/?utm_source=remotive&amp;utm_medium=job_ad&amp;utm_campaign=supply_en_graphic_designer_jul_2026_job_ad\" rel=\"nofollow\" target=\"_self\">Lemon.io</a></span> \u2014 the marketplace that connects you with hand-picked startups in the US and Europe.</p>\n<p><strong>\u00a0</strong></p>\n<p><strong>What we offer:</strong></p>\n<p><!-- notionvc: a7347a7d-affa-459b-a665-28685b353da4 --></p>\n<ul style=\"\">\n<li style=\"\">The rate depends on your skills and experience. We''ve already paid out over $11M to our engineers &amp; designers<!-- notionvc: f88131f3-f381-4982-84d7-db268f06b00b -->.</li>\n<li style=\"\">No more hunting for clients or negotiating rates \u2014 let us handle the business side of things so you can focus on what you do best.</li>\n<li style=\"\">Choose a schedule that works best for you. It\u2019s possible to communicate async or minimally overlap within team working hours.</li>\n<li style=\"\">We respect your seniority so you can expect no micromanagement or screen trackers.</li>\n<li style=\"\">Communicate directly with the clients. Sounds good, yeah?</li>\n<li style=\"\">Most of our projects involve working in a fast-paced startup environment. We hope you like it as much as we do.</li>\n</ul>\n<p>\u00a0</p>\n<p><strong>Requirements:</strong></p>\n<ul style=\"\">\n<li style=\"\">5+ years of experience in Graphic Design</li>\n<li style=\"\">5+ years of commercial experience with Adobe Creative Suite &amp; Adobe Illustrator</li>\n</ul>\n<p><strong>\u00a0</strong></p>\n<p><strong>Other requirements:</strong></p>\n<p><!-- notionvc: 88a68410-a615-422f-b541-6d39b253849c --></p>\n<ul style=\"\">\n<li style=\"\"><strong>Strong design craft</strong> \u2014 as a Senior Designer, you''re expected to build polished, production-ready work from scratch, with a solid grasp of design systems, component architecture, and how your decisions translate into real product or brand outcomes.</li>\n<li style=\"\"><strong>Clear and confident communication in English</strong> \u2014 advanced ability to discuss creative briefs, defend design decisions, and flag blockers early. Strong self-presentation is essential, particularly on client calls.</li>\n<li style=\"\"><strong>High ownership, zero hand-holding</strong> \u2014 you thrive working full-time remotely, manage your own time, and consistently hit deadlines without being chased.</li>\n<li style=\"\"><strong>Reliability</strong> \u2014 we need to trust you completely. If you commit to something, you deliver it. If something changes, you communicate early.</li>\n<li style=\"\"><strong>Fast ramp-up</strong> \u2014 you can absorb project context quickly, align with existing style guides or brand directions, and start producing valuable work within the first days, not weeks.</li>\n</ul>\n<p>\u00a0</p>\n<p><strong>NOT YOUR TECH STACK?</strong></p>\n<p><!-- notionvc: 57636cf0-d4d3-4b8c-a26a-f114e1051d54 --></p>\n<p>We have a variety of projects, so if you have 4+ years of commercial software development experience and are proficient in AI Agent Architecture, AI Automation Architecture, AI Engineering, Site Reliability Engineering, Platform Engineering, React &amp; Python, React &amp; Golang, Golang, React &amp; Java, React &amp; Ruby, Ruby, PHP &amp; Vue, Vue &amp; Node.js, React &amp; .NET, Android &amp; iOS, iOS &amp; Swift, Flutter &amp; Dart, Blockchain (Ethereum/Ethers.js/Wagmi/Viem/Solana), Angular &amp; Node.js, Vue &amp; .NET, Python &amp; Vue, DevOps, MLOps, Data Science, Angular &amp; PHP, Angular &amp; .NET, Symfony &amp; React, Symfony &amp; Vue, Symfony &amp; Angular, Python, Symfony &amp; JavaScript &amp; Next.js &amp; TypeScript, Data Analysis, React &amp; PHP, Data Engineering, Project Management, Product Management, QA Automation, QA Manual, Embedded Software Engineering, React Native &amp; Node, React Native &amp; React, React Native &amp; Ruby, React Native &amp; Python, WordPress, Android, Data Annotation, Angular, Python &amp; Node, React &amp; Node.js, Java &amp; Spring, Svelte &amp; Python, Svelte &amp; Node.js, Svelte &amp; TypeScript, Rust, Shopify &amp; JavaScript, Vue &amp; Nuxt, PHP &amp; Laravel, Animation, Graphic Design, React &amp; Node &amp; React Native, .NET &amp; C#, Electron, Scala, C++, Unreal Engine &amp; C++, Python &amp; LLM, Unity, or Machine Learning Engineering, we would be happy to connect with you and match you with a project that fits your experience.</p>\n<img src=\"https://remotive.com/job/track/2091081/blank.gif?source=public_api\" alt=\"\"/>", "company_logo_url": "https://remotive.com/job/2091081/logo"}', '2026-07-01', '2026-07-28T14:23:05+00:00'),
  (12201, 'web3', '152486', '{"id": 152486, "date": "Mon, 10 Aug 2026 22:04:14 +0100", "date_epoch": 1786395854, "is_remote": true, "country": "united-kingdom", "city": null, "title": "AI Research Engineer (Pre-training - LLM & Multi-Modal) - 100% Remote Worldwide", "company": "Tether Operations Limited", "location": " ABC United Kindom GB", "apply_url": "https://web3.career/r/2gDNyUTM__fnNFpS", "tags": ["remote", "research", "ai", "engineer", "education", "bitcoin", "blockchain", "pytorch"], "salary_min_value": null, "salary_max_value": null, "salary_currency": null, "salary_unit": null, "estimated_min_salary": 100000, "estimated_max_salary": 500000, "estimated_avg_salary": 300000, "description": "<p><strong><em>Join Tether and Shape the Future of Digital Finance</em></strong></p><p>At Tether, we\u2019re not just building products, we\u2019re pioneering a global financial revolution. Our cutting-edge solutions empower businesses\u2014from exchanges and wallets to payment processors and ATMs\u2014to seamlessly integrate reserve-backed tokens across blockchains. By harnessing the power of blockchain technology, Tether enables you to store, send, and receive digital tokens instantly, securely, and globally, all at a fraction of the cost. Transparency is the bedrock of everything we do, ensuring trust in every transaction.</p><p></p><p><strong><em>Innovate with Tether</em></strong></p><p><strong>Tether Finance: </strong>Our innovative product suite features the world\u2019s most trusted stablecoin, <strong>USDT</strong>, relied upon by hundreds of millions worldwide, alongside pioneering digital asset tokenization services.</p><p>But that\u2019s just the beginning:</p><p><strong>Tether Power: </strong>Driving sustainable growth, our energy solutions optimize excess power for Bitcoin mining using eco-friendly practices in state-of-the-art, geo-diverse facilities.</p><p><strong>Tether Data: </strong>Fueling breakthroughs in AI and peer-to-peer technology, we reduce infrastructure costs and enhance global communications with cutting-edge solutions like <strong>KEET</strong>, our flagship app that redefines secure and private data sharing.</p><p><strong>Tether Education</strong>: Democratizing access to top-tier digital learning, we empower individuals to thrive in the digital and gig economies, driving global growth and opportunity.</p><p><strong>Tether Evolution</strong>: At the intersection of technology and human potential, we are pushing the boundaries of what is possible, crafting a future where innovation and human capabilities merge in powerful, unprecedented ways.</p><p></p><p><strong><em>Why Join Us?</em></strong></p><p>Our team is a global talent powerhouse, working remotely from every corner of the world. If you\u2019re passionate about making a mark in the fintech space, this is your opportunity to collaborate with some of the brightest minds, pushing boundaries and setting new standards. We\u2019ve grown fast, stayed lean, and secured our place as a leader in the industry.</p><p>If you have excellent English communication skills and are ready to contribute to the most innovative platform on the planet, Tether is the place for you.</p><p><strong>Are you ready to be part of the future?</strong></p><p></p><p><strong>About the job</strong></p><p><span>As a member of the AI model team, you will drive innovation in architecture development for cutting-edge models of various scales, including small, large, and multi-modal systems. Your work will enhance intelligence, improve efficiency, and introduce new capabilities to advance the field.</span></p><p><span>You will have a deep expertise in Large Language Model (LLM) and Multi-Modal architectures, a strong grasp of pre-training optimization, and a hands-on, research-driven approach. Your mission is to explore and implement novel techniques and algorithms that lead to groundbreaking advancements: multi-modal data curation and alignment, strengthening baselines, and identifying and resolving existing pre-training bottlenecks to push the limits of cross-modal AI performance.</span></p><p></p><p><strong>Responsibilities</strong></p><ul>\n<li><p><strong><span>Large-Scale Pre-Training:</span></strong><span> Conduct foundational pre-training for LLMs and Multi-Modal models (integrating text, vision, audio, or other modalities) on large, distributed servers equipped with multi-nodes &amp; thousands of NVIDIA GPUs.</span></p></li>\n<li><p><strong><span>Architecture &amp; Alignment Innovation: </span></strong><span>Design, prototype, and scale innovative architectures, tokenizers, and cross-modal alignment layers to enhance model intelligence and multi-modal understanding.</span></p></li>\n<li><p><strong><span>Data Strategy: </span></strong><span>Source, filter, and curate massive-scale textual and multi-modal datasets, establishing robust data pipelines for efficient pre-training.</span></p></li>\n<li><p><strong><span>Experimental Research:</span></strong><span> Independently and collaboratively execute experiments, analyze results, and refine training methodologies for optimal performance and token efficiency.</span></p></li>\n<li><p><strong><span>Optimization &amp; Debugging:</span></strong><span> Investigate, debug, and eliminate bottlenecks in model efficiency, computational performance, and multi-modal alignment stability during long training runs.</span></p></li>\n<li><p><strong><span>System Scalability: </span></strong><span>Contribute to the advancement of distributed training systems to ensure seamless scalability and hardware efficiency on target platforms.</span></p></li>\n</ul><br><ul>\n<li><p><span>A degree in Computer Science\u00a0 or related field. Ideally PhD in NLP, Machine Learning, or a related field, complemented by a solid track record in AI R&amp;D (with good publications in A* conferences).</span></p></li>\n<li><p><span>Hands-on experience contributing to large-scale LLM or Multi-Modal pre-training runs on large, distributed servers equipped with thousands of NVIDIA GPUs, ensuring scalability and impactful advancements in model performance.</span></p></li>\n<li><p><span>Familiarity and practical experience with large-scale, distributed training frameworks, libraries and tools.</span></p></li>\n<li><p><span>Deep knowledge of state-of-the-art transformer and non-transformer modifications aimed at enhancing intelligence, efficiency and scalability.</span></p></li>\n<li><p><span>Strong expertise in PyTorch and Hugging Face libraries with practical experience in model development, continual pretraining, and deployment.</span></p></li>\n</ul><p></p><p><strong>Important information for candidates</strong><br>Recruitment scams have become increasingly common. To protect yourself, please keep the following in mind when applying for roles:</p><ul>\n<li><p><strong>Apply only through our official channels.</strong>\u00a0We do not use third-party platforms or agencies for recruitment unless clearly stated. All open roles are listed on our official careers page:\u00a0https://tether.recruitee.com/</p></li>\n<li><p><strong>Verify the recruiter\u2019s identity.</strong>\u00a0All our recruiters have verified LinkedIn profiles. If you\u2019re unsure, you can confirm their identity by checking their profile or contacting us through our website.</p></li>\n<li><p><strong>Be cautious of unusual communication methods.</strong>\u00a0We do not conduct interviews over WhatsApp, Telegram, or SMS. All communication is done through official company emails and platforms.</p></li>\n<li><p><strong>Double-check email addresses.</strong>\u00a0All communication from us will come from emails ending in\u00a0<strong>@</strong>tether.to<strong> or\u00a0@</strong>tether.io</p></li>\n<li><p><strong>We will never request payment or financial details.</strong>\u00a0If someone asks for personal financial information or payment at any point during the hiring process, it is a scam. Please report it immediately.</p></li>\n</ul><p><strong>When in doubt, feel free to reach out through our official website.</strong></p>\n When applying, mention the word CANDYSHOP to show you read the job post completely."}', '2026-08-01', '2026-08-10T21:04:14+00:00'),
  (13456, 'habr', '1000168179', '{"id": 1000168179, "href": "/vacancies/1000168179", "title": "Разработчик GreenData", "isMarked": true, "remoteWork": true, "salaryQualification": {"title": "Старший (Senior)", "href": "/vacancies?qid=5"}, "publishedDate": {"date": "2026-08-12T15:33:58+03:00", "title": "12 августа"}, "location": null, "company": {"id": 1000119306, "alias_name": "top-selection", "href": "/companies/top-selection", "title": "Top Selection", "accredited": false, "logo": {"src": "https://habrastorage.org/getpro/moikrug/uploads/company/100/008/086/9/logo/medium_471913a34c9e1fd546aecd2d816485c8.png"}, "rating": null}, "employment": "full_time", "salary": {"from": 230000, "to": 250000, "currency": "rur", "formatted": "от 230 000 до 250 000 ₽"}, "divisions": [{"title": "Бэкенд разработчик", "href": "/vacancies/spec/development/backend"}], "skills": [{"title": "SQL", "href": "/vacancies/programmist_sql"}, {"title": "Алгоритмы", "href": "/vacancies/skills/algoritmy"}, {"title": "Groovy", "href": "/vacancies/skills/groovy"}], "media": null, "locations": null, "favorite": false, "archived": false, "hidden": false, "can_edit": false, "userVacancyBanHref": "/api/frontend/user_vacancy_bans", "quickResponseHref": "/api/frontend/quick_responses", "qualification": "Senior", "predictedSalary": null, "reactions": {"items": [{"name": "arrow", "title": "arrow", "hasReacted": false, "count": 0, "image": "/images/emoji/1f3af.svg"}, {"name": "bang", "title": "bang", "hasReacted": false, "count": 0, "image": "/images/emoji/1f4a5.svg"}, {"name": "cash", "title": "cash", "hasReacted": false, "count": 0, "image": "/images/emoji/1f4b0.svg"}, {"name": "boom", "title": "boom", "hasReacted": false, "count": 0, "image": "/images/emoji/1f389.svg"}, {"name": "fire", "title": "fire", "hasReacted": false, "count": 0, "image": "/images/emoji/1f525.svg"}, {"name": "glass", "title": "glass", "hasReacted": false, "count": 0, "image": "/images/emoji/1f942.svg"}, {"name": "snow", "title": "snow", "hasReacted": false, "count": 0, "image": "/images/emoji/2744.svg"}, {"name": "heart", "title": "heart", "hasReacted": false, "count": 0, "image": "/images/emoji/2764.svg"}], "fallbackHref": "https://career.habr.com/users/auth/tmid"}, "response": {"kind": "guest"}, "hasPublishedCBP": true, "color": "#001C66", "description_html": "<div class=\"style-ugc\"><p><strong>Позиция:</strong> Разработчик GreenData<br/><strong>Вилка: </strong>230.000 - 270.000 gross<br/><strong>Занятость: </strong>Полная<br/><strong>Формат работы:</strong> Удаленный<br/><strong>Локация:</strong> РФ<br/><strong>Оформление:</strong> ИП<br/><strong>Компания: </strong>Top Selection<br/><br/>Привет! Меня зовут Марина. Я представляю группу компаний Top Selection.<br/>Мы занимаемся трудоустройством IT специалистов на проектную занятость.<br/>На данный момент мы в поиске Разработчика GreenData<br/><br/>💥Обязательные требования: <br/> • Опыт работы с платформой GreenData — строго от 1,5 лет.<br/> • Опыт самостоятельной настройки UI, процессов и сложных алгоритмов.<br/> • Знание языка Groovy.<br/> • Отличное знание SQL.<br/> • Опыт настройки отчетов и дашбордов</p></div>"}', '2026-08-01', '2026-08-12T12:33:58+00:00');

