  (50, 2, 3, 'We The Flywheel', 'AI-Native Tech & Growth Director', 'REMOTE (worldwide)', 'staff+', 'remote', 'contract', ARRAY['ai']::text[], NULL, NULL, NULL, '{"stack": "deeply AI-native workflows", "title": "AI-Native Tech & Growth Director", "company": "We The Flywheel", "location": "REMOTE (worldwide)", "description": "We''re a remote-first digital product studio building across sports media, AI, fitness, and personal branding — 500+ web properties and deeply AI-native workflows. AI does the heavy lifting here, but it''s the leverage, not the point: we hire for the human judgment, ingenuity, and taste on top of it.", "remote_policy": "REMOTE (worldwide)", "employment_type": "Contract / Part-time (10–40 hrs/wk)"}'::jsonb, 'We''re a remote-first digital product studio building across sports media, AI, fitness, and personal branding — 500+ web properties and deeply AI-native workflows. AI does the heavy lifting here, but it''s the leverage, not the point: we hire for the human judgment, ingenuity, and taste on top of it.', ARRAY[]::text[]),
  (51, 2, 4, 'We The Flywheel', 'Head of Data Science', 'REMOTE (worldwide)', 'staff+', 'remote', 'contract', ARRAY['ai']::text[], NULL, NULL, NULL, '{"stack": "deeply AI-native workflows", "title": "Head of Data Science", "company": "We The Flywheel", "location": "REMOTE (worldwide)", "description": "We''re a remote-first digital product studio building across sports media, AI, fitness, and personal branding — 500+ web properties and deeply AI-native workflows. AI does the heavy lifting here, but it''s the leverage, not the point: we hire for the human judgment, ingenuity, and taste on top of it.", "remote_policy": "REMOTE (worldwide)", "employment_type": "Contract / Part-time (10–40 hrs/wk)"}'::jsonb, 'We''re a remote-first digital product studio building across sports media, AI, fitness, and personal branding — 500+ web properties and deeply AI-native workflows. AI does the heavy lifting here, but it''s the leverage, not the point: we hire for the human judgment, ingenuity, and taste on top of it.', ARRAY[]::text[]),
  (52, 3, 0, 'SmarterDx', NULL, 'Remote (US only)', 'unknown', 'remote', 'unknown', ARRAY[]::text[], 12500, 20833, NULL, '{"salary": "150-250k+ + equity + benefits", "company": "SmarterDx", "location": "Remote (US only)", "description": "Our physician-designed clinical AI platform reviews the clinical record, understands the nuance of patient care, and helps hospitals capture appropriate reimbursement across the revenue cycle.", "remote_policy": "Remote (US only)"}'::jsonb, 'Our physician-designed clinical AI platform reviews the clinical record, understands the nuance of patient care, and helps hospitals capture appropriate reimbursement across the revenue cycle.', ARRAY['salary_currency', 'salary_max', 'salary_min']::text[]),
  (54, 5, 0, 'WireScreen', 'Senior Software Engineer (Frontend)', 'NYC', 'senior', 'hybrid', 'full-time', ARRAY['react', 'react framework', 'component-based design system', 'data visualization']::text[], 14167, 18333, 'USD', '{"stack": "significant React experience as well as experience with at least one React framework, plus prior experience building or contributing to a component-based design system & data viz work", "title": "Senior Software Engineer (Frontend)", "salary": "$170k-$220k (frontend) + equity", "company": "WireScreen", "location": "NYC - hybrid", "seniority": "senior software engineers", "description": "We’re looking for senior software engineers on the frontend to help build the future of our platform: transitioning us to a component-based system all the way through to building beautiful pages that visualize the story of ownership, power, and influence in the Chinese corporate world.", "remote_policy": "NYC - hybrid", "employment_type": "Full-time"}'::jsonb, 'We’re looking for senior software engineers on the frontend to help build the future of our platform: transitioning us to a component-based system all the way through to building beautiful pages that visualize the story of ownership, power, and influence in the Chinese corporate world.', ARRAY['salary_currency', 'salary_max', 'salary_min']::text[]),
  (107, 26, 0, 'DoubleVerify (DV Scibids)', 'Sr. Data Engineer I', 'New York, NY', 'senior', 'hybrid', 'full-time', ARRAY['python', 'sql', 'bigquery', 'cloud sql', 'cloud datastore', 'cloud run', 'gcp', 'prefect', 'docker', 'ci-cd', 'git', 'java', 'rust']::text[], 7417, 14833, 'USD', '{"stack": "Stack: Python, SQL, BigQuery, Cloud SQL, Cloud Datastore, Cloud Run (GCP), Prefect, Docker, CI/CD, Git. Java or Rust a plus.", "title": "Sr. Data Engineer I", "salary": "$89K–$178K", "company": "DoubleVerify (DV Scibids)", "location": "New York, NY", "seniority": "Sr. Data Engineer I", "description": "In this role you will own and build backend services and data pipelines that power product expansion — exploring external partner APIs, designing reliable ingestion and reconciliation layers, exposing internal endpoints for other DV teams, and keeping production systems observable and performant at scale.", "remote_policy": "ONSITE/HYBRID - New York, NY (3x/week)", "employment_type": "Full-time"}'::jsonb, 'In this role you will own and build backend services and data pipelines that power product expansion — exploring external partner APIs, designing reliable ingestion and reconciliation layers, exposing internal endpoints for other DV teams, and keeping production systems observable and performant at scale.', ARRAY['salary_currency', 'salary_max', 'salary_min']::text[]),
  (644, 829, 0, 'Lemon.io', 'Senior Designer', 'Remote', 'senior', 'remote', 'full-time', ARRAY['adobe creative suite', 'adobe illustrator', 'graphic design', 'design systems']::text[], NULL, NULL, NULL, '{"stack": "5+ years of commercial experience with Adobe Creative Suite & Adobe Illustrator", "title": "Senior Designer", "salary": "The rate depends on your skills and experience.", "company": "Lemon.io", "seniority": "We respect your seniority", "description": "as a Senior Designer, you''re expected to build polished, production-ready work from scratch, with a solid grasp of design systems, component architecture, and how your decisions translate into real product or brand outcomes.", "remote_policy": "you thrive working full-time remotely", "employment_type": "you thrive working full-time remotely"}'::jsonb, 'As a Senior Designer, you''re expected to build polished, production-ready work from scratch, with a solid grasp of design systems, component architecture, and how your decisions translate into real product or brand outcomes.', ARRAY[]::text[]),
  (1161, 12201, 0, 'Tether', 'AI Model Engineer (LLM & Multi-Modal)', 'Global (Remote)', 'senior', 'remote', 'unknown', ARRAY['pytorch', 'hugging face', 'nvidia gpus', 'distributed training', 'llm', 'multi-modal', 'transformers']::text[], NULL, NULL, NULL, '{"stack": "Strong expertise in PyTorch and Hugging Face libraries with practical experience in model development, continual pretraining, and deployment.", "title": "As a member of the AI model team, you will drive innovation in architecture development for cutting-edge models of various scales, including small, large, and multi-modal systems.", "company": "At Tether, we’re not just building products, we’re pioneering a global financial revolution.", "location": "Our team is a global talent powerhouse, working remotely from every corner of the world.", "seniority": "Ideally PhD in NLP, Machine Learning, or a related field, complemented by a solid track record in AI R&D (with good publications in A* conferences).", "description": "As a member of the AI model team, you will drive innovation in architecture development for cutting-edge models of various scales, including small, large, and multi-modal systems. Your work will enhance intelligence, improve efficiency, and introduce new capabilities to advance the field.", "remote_policy": "Our team is a global talent powerhouse, working remotely from every corner of the world."}'::jsonb, 'As a member of the AI model team, you will drive innovation in architecture development for cutting-edge models of various scales, including small, large, and multi-modal systems. Your work will enhance intelligence, improve efficiency, and introduce new capabilities to advance the field.', ARRAY[]::text[]),
  (89, 13456, 0, 'Top Selection', 'Разработчик GreenData', 'РФ', 'senior', 'remote', 'full-time', ARRAY['greendata', 'groovy', 'sql']::text[], 230000, 250000, 'RUB', '{"stack": "Знание языка Groovy. Отличное знание SQL.", "title": "Разработчик GreenData", "salary": "230.000 - 270.000 gross", "company": "Top Selection", "location": "РФ", "remote_policy": "Удаленный", "employment_type": "Полная"}'::jsonb, 'Опыт работы с платформой GreenData — строго от 1,5 лет. Опыт самостоятельной настройки UI, процессов и сложных алгоритмов. Знание языка Groovy. Отличное знание SQL. Опыт настройки отчетов и дашбордов', ARRAY['salary_currency', 'salary_max', 'salary_min', 'seniority']::text[]);

